// Package sqlite holds the SQLite storage of the research agents' data model (package core): the schema (Schema) and the functions
// that write and read its tables (Store).
package sqlite

import _ "embed"

// Schema is the schema for SQLite: one table per struct of package core, the Run and its States. The IDs are generated by the
// database. Times are UTC RFC 3339 strings (SQLite has no datetime type). Foreign keys must be on (PRAGMA foreign_keys = ON). The
// statements are idempotent and in dependency order, so the whole schema can be executed in one call.
//
//go:embed schema.sql
var Schema string

// Upgrade is what an older database lacks: the columns parent_id, name and reason of gb_agent_research_runs (before sub-agents, 0.129.0)
// and runner (before the Modal runner, 0.165.0), and agent_name, agent_version and agent_hash (before the agent definitions, 0.168.0), and notes_id (before the deep-research loop state, 0.180.0).
// SQLite has no ADD COLUMN IF NOT EXISTS, so each statement is run only if its column is missing (see the Open of package
// agent_research).
var Upgrade = []struct{ Column, Statement string }{
	{"parent_id", `ALTER TABLE gb_agent_research_runs ADD COLUMN parent_id INTEGER REFERENCES gb_agent_research_runs(id) ON DELETE CASCADE`},
	{"name", `ALTER TABLE gb_agent_research_runs ADD COLUMN name TEXT NOT NULL DEFAULT ''`},
	{"reason", `ALTER TABLE gb_agent_research_runs ADD COLUMN reason TEXT NOT NULL DEFAULT ''`},
	{"runner", `ALTER TABLE gb_agent_research_runs ADD COLUMN runner TEXT NOT NULL DEFAULT 'local'`},
	{"agent_name", `ALTER TABLE gb_agent_research_runs ADD COLUMN agent_name TEXT NOT NULL DEFAULT ''`},
	{"agent_version", `ALTER TABLE gb_agent_research_runs ADD COLUMN agent_version TEXT NOT NULL DEFAULT ''`},
	{"agent_hash", `ALTER TABLE gb_agent_research_runs ADD COLUMN agent_hash TEXT NOT NULL DEFAULT ''`},
	{"notes_id", `ALTER TABLE gb_agent_research_runs ADD COLUMN notes_id TEXT NOT NULL DEFAULT ''`},
}

// SubagentIndexes are the indexes on the columns of Upgrade, so that they are made after it: the sub-agents of a run, and the rule
// that the name of a sub-agent is unique among those of its parent.
//
//go:embed schema_subagent_indexes.sql
var SubagentIndexes string

// StatusMigration is what a database made before the status 'stopped' (0.145.0) lacks: its CHECK on gb_agent_research_runs.status does not
// allow it. SQLite cannot change a constraint, so the table is rebuilt (the steps of https://sqlite.org/lang_altertable.html#otheralter):
// run it on one connection with foreign keys off, in a transaction, and make the indexes again after it (Schema). Only needed when
// the table's SQL (sqlite_master) does not mention 'stopped' (see the Open of package agent_research).
//
//go:embed upgrade_status.sql
var StatusMigration string
